/// <reference lib="webworker" />

import { cleanupOutdatedCaches, precacheAndRoute } from 'workbox-precaching';
import { NavigationRoute, registerRoute } from 'workbox-routing';
import { CacheFirst, NetworkFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';

declare const self: ServiceWorkerGlobalScope;

// Precache all the assets generated by your build process.
// Their URLs are injected into the manifest variable below.
// This variable must be present somewhere in your service worker file.
precacheAndRoute(self.__WB_MANIFEST);

// Clean up outdated caches
cleanupOutdatedCaches();

// Cache the main document with NetworkFirst strategy
registerRoute(
  ({ request }) => request.mode === 'navigate',
  new NetworkFirst({
    cacheName: 'documents-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 60 * 60 * 24 * 7, // 7 days
      }),
    ],
  })
);

// Cache static assets (CSS, JS) with StaleWhileRevalidate
registerRoute(
  ({ request }) =>
    request.destination === 'style' ||
    request.destination === 'script' ||
    request.destination === 'worker',
  new StaleWhileRevalidate({
    cacheName: 'static-assets-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 60 * 60 * 24 * 30, // 30 days
      }),
    ],
  })
);

// Cache images with CacheFirst strategy
registerRoute(
  ({ request }) => request.destination === 'image',
  new CacheFirst({
    cacheName: 'images-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 60 * 60 * 24 * 30, // 30 days
      }),
    ],
  })
);

// Cache FFmpeg.wasm core files with CacheFirst strategy
registerRoute(
  ({ url }) => 
    url.hostname === 'unpkg.com' && 
    url.pathname.includes('@ffmpeg/core'),
  new CacheFirst({
    cacheName: 'ffmpeg-core-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 10,
        maxAgeSeconds: 60 * 60 * 24 * 365, // 1 year - these rarely change
      }),
    ],
  })
);

// Cache other external dependencies
registerRoute(
  ({ url }) => 
    url.hostname === 'unpkg.com' ||
    url.hostname === 'cdn.jsdelivr.net',
  new StaleWhileRevalidate({
    cacheName: 'cdn-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 30,
        maxAgeSeconds: 60 * 60 * 24 * 7, // 7 days
      }),
    ],
  })
);

// Handle offline fallback for navigation requests
const navigationHandler = new NetworkFirst({
  cacheName: 'documents-cache',
});

const navigationRoute = new NavigationRoute(navigationHandler, {
  denylist: [
    // Exclude API routes or other non-document requests
    /^\/_/,
    /\/api\//,
  ],
});

registerRoute(navigationRoute);

// Skip waiting and claim clients immediately
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// Claim control of all pages immediately
self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

// Handle install event
self.addEventListener('install', () => {
  console.log('Service Worker installing');
  // Skip waiting to activate new service worker immediately
  self.skipWaiting();
});

// Handle activate event
self.addEventListener('activate', (activateEvent) => {
  console.log('Service Worker activated');
  activateEvent.waitUntil(self.clients.claim());
});

// Handle fetch events for better offline support
self.addEventListener('fetch', (fetchEvent) => {
  // Let the browser handle non-GET requests
  if (fetchEvent.request.method !== 'GET') {
    return;
  }

  // Handle Cross-Origin Isolation headers for FFmpeg.wasm
  if (fetchEvent.request.url.includes('ffmpeg')) {
    fetchEvent.respondWith(
      caches.match(fetchEvent.request).then((response) => {
        if (response) {
          // Clone the response to add headers
          const newHeaders = new Headers(response.headers);
          newHeaders.set('Cross-Origin-Embedder-Policy', 'require-corp');
          newHeaders.set('Cross-Origin-Opener-Policy', 'same-origin');
          
          return new Response(response.body, {
            status: response.status,
            statusText: response.statusText,
            headers: newHeaders,
          });
        }
        
        // If not in cache, fetch with proper headers
        return fetch(fetchEvent.request).then((fetchResponse) => {
          const newHeaders = new Headers(fetchResponse.headers);
          newHeaders.set('Cross-Origin-Embedder-Policy', 'require-corp');
          newHeaders.set('Cross-Origin-Opener-Policy', 'same-origin');
          
          return new Response(fetchResponse.body, {
            status: fetchResponse.status,
            statusText: fetchResponse.statusText,
            headers: newHeaders,
          });
        });
      })
    );
  }
});

export {};